app.post('/api/create-table',auth,async(req,res)=>{ try{ let u=await getUser(req); let {game,type,mise}=req.body; mise=parseFloat(mise||0); let min=(game==="loto"?10:5); if(mise<min) return res.status(400).json({message:"Minimum: "+min+"$ - Mila Depot / Appel @ Fond aloha"}); if(parseFloat(u.balance)<mise) return res.status(400).json({message:"Solde tsy ampy - Manaova Depot / Appel @ Fond aloha"}); await pool.query("UPDATE users SET balance=balance-$1 WHERE id=$2",[mise,u.id]); let commission=+(mise*0.10).toFixed(2); let fond=+(mise-commission).toFixed(2); let code=String(Math.floor(1000+Math.random()*9000)); await pool.query("INSERT INTO tables_tbl(code,game,type,mise,commission,fond,players,creator,creator_nom,timer,date) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,'2min30s',$10)",[code,game,type,mise,commission,fond,JSON.stringify([u.id]),u.id,u.nom,now()]); res.json({message:"Table cree - Appel @ Fond OK",table:{code,game,type,mise,commission,fond}}); }catch(e){ res.status(500).json({message:e.message}); } });
